// TestRoleVariable tests variable parsing
func TestRoleVariable(t *testing.T) {
	var tests = []struct {
		title string
		in    string
		err   error
		out   Expression
	}{
		{
			title: "no curly bracket prefix",
			in:    "external.foo}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid syntax",
			in:    `{{external.foo("bar")`,
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid variable syntax",
			in:    "{{internal.}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid dot syntax",
			in:    "{{external..foo}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "empty variable",
			in:    "{{}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "no curly bracket suffix",
			in:    "{{internal.foo",
			err:   trace.BadParameter(""),
		},
		{
			title: "too many levels of nesting in the variable",
			in:    "{{internal.foo.bar}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "valid with brackets",
			in:    `{{internal["foo"]}}`,
			out:   Expression{namespace: "internal", variable: "foo"},
		},
		{
			title: "string literal",
			in:    `foo`,
			out:   Expression{namespace: LiteralNamespace, variable: "foo"},
		},
		{
			title: "external with no brackets",
			in:    "{{external.foo}}",
			out:   Expression{namespace: "external", variable: "foo"},
		},
		{
			title: "internal with no brackets",
			in:    "{{internal.bar}}",
			out:   Expression{namespace: "internal", variable: "bar"},
		},
		{
			title: "internal with spaces removed",
			in:    "  {{  internal.bar  }}  ",
			out:   Expression{namespace: "internal", variable: "bar"},
		},
		{
			title: "variable with prefix and suffix",
			in:    "  hello,  {{  internal.bar  }}  there! ",
			out:   Expression{prefix: "hello,  ", namespace: "internal", variable: "bar", suffix: "  there!"},
		},
		{
			title: "variable with local function",
			in:    "{{email.local(internal.bar)}}",
			out:   Expression{namespace: "internal", variable: "bar", transform: emailLocalTransformer{}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.title, func(t *testing.T) {
			variable, err := Variable(tt.in)
			if tt.err != nil {
				assert.IsType(t, tt.err, err)
				return
			}
			assert.NoError(t, err)
			assert.Empty(t, cmp.Diff(tt.out, *variable, cmp.AllowUnexported(Expression{})))
		})
	}
}

func TestMatch(t *testing.T) {
	tests := []struct {
		name  string
		value string
		cases map[string]bool
	}{
		{
			name:  "literal",
			value: "a.b",
			cases: map[string]bool{"a.b": true, "axb": false, "xa.b": false},
		},
		{
			name:  "wildcard",
			value: "foo*bar",
			cases: map[string]bool{"foobar": true, "foo123bar": true, "foo123barx": false},
		},
		{
			name:  "standalone wildcard",
			value: "*",
			cases: map[string]bool{"": true, "anything": true},
		},
		{
			name:  "raw regexp",
			value: "^foo[0-9]+$",
			cases: map[string]bool{"foo123": true, "foo": false, "xfoo123": false},
		},
		{
			name:  "regexp.match",
			value: "{{regexp.match(\"b.r\")}}",
			cases: map[string]bool{"bar": true, "a-bar-z": true, "baz": false},
		},
		{
			name:  "regexp.not_match",
			value: "{{regexp.not_match(\"bar\")}}",
			cases: map[string]bool{"bar": false, "foo-bar": false, "baz": true},
		},
		{
			name:  "static prefix and suffix",
			value: "foo-{{regexp.match(\"^bar$\")}}-baz",
			cases: map[string]bool{"foo-bar-baz": true, "foo-barx-baz": false, "foo-bar-qux": false},
		},
		{
			name:  "negation with static text",
			value: "foo-{{regexp.not_match(\"bar\")}}-baz",
			cases: map[string]bool{"foo-qux-baz": true, "foo-bar-baz": false, "foo-qux-bazz": false},
		},
		{
			name:  "overlapping prefix and suffix",
			value: "aa{{regexp.not_match(\"x\")}}aa",
			cases: map[string]bool{"aaa": false, "aaaa": true},
		},
		{
			name:  "preserve static whitespace",
			value: " pre {{ regexp.match(\"x\") }} post ",
			cases: map[string]bool{" pre x post ": true, "pre x post": false},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			matcher, err := Match(tt.value)
			if !assert.NoError(t, err) {
				return
			}
			for in, want := range tt.cases {
				assert.Equal(t, want, matcher.Match(in), "input %q", in)
			}
		})
	}
}

func TestMatcherErrors(t *testing.T) {
	tests := []struct {
		name    string
		value   string
		message string
	}{
		{
			name:    "missing opening brackets",
			value:   "regexp.match(\"foo\")}}",
			message: "\"regexp.match(\\\"foo\\\")}}\" is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{expression}}",
		},
		{
			name:    "missing closing brackets",
			value:   "{{regexp.match(\"foo\")",
			message: "\"{{regexp.match(\\\"foo\\\")\" is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{expression}}",
		},
		{
			name:    "unsupported namespace",
			value:   "{{other.match(\"foo\")}}",
			message: "unsupported function namespace other, supported namespaces are email and regexp",
		},
		{
			name:    "unsupported regexp function",
			value:   "{{regexp.other(\"foo\")}}",
			message: "unsupported function regexp.other, supported functions are: regexp.match, regexp.not_match.",
		},
		{
			name:    "unsupported email function",
			value:   "{{email.other(\"foo\")}}",
			message: "unsupported function email.other, supported functions are: email.local",
		},
		{
			name:    "variable",
			value:   "{{internal.foo}}",
			message: "\"internal.foo\" is not a valid matcher expression - no variables and transformations are allowed",
		},
		{
			name:    "transformation",
			value:   "{{email.local(\"foo@example.com\")}}",
			message: "\"email.local(\\\"foo@example.com\\\")\" is not a valid matcher expression - no variables and transformations are allowed",
		},
		{
			name:    "multiple expressions",
			value:   "{{regexp.match(\"foo\") + regexp.match(\"bar\")}}",
			message: "\"regexp.match(\\\"foo\\\") + regexp.match(\\\"bar\\\")\" is not a valid matcher expression - no variables and transformations are allowed",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			matcher, err := Match(tt.value)
			assert.Nil(t, matcher)
			if assert.True(t, trace.IsBadParameter(err), "error: %v", err) {
				assert.EqualError(t, err, tt.message)
			}
		})
	}

	for _, value := range []string{
		"{{regexp.match()}}",
		"{{regexp.match(\"foo\", \"bar\")}}",
		"{{regexp.match(internal.foo)}}",
		"{{regexp.match(42)}}",
		"{{regexp.match(regexp.match(\"foo\"))}}",
		"{{email.local(internal.foo)}}",
	} {
		t.Run(value, func(t *testing.T) {
			_, err := Match(value)
			assert.True(t, trace.IsBadParameter(err), "error: %v", err)
		})
	}

	for _, value := range []string{"{{regexp.match(\"[\")}}", "{{regexp.not_match(\"[\")}}"} {
		t.Run(value, func(t *testing.T) {
			_, err := Match(value)
			if assert.True(t, trace.IsBadParameter(err), "error: %v", err) {
				assert.True(t, strings.HasPrefix(err.Error(), "failed parsing regexp \"[\": "), "error: %v", err)
			}
		})
	}
}

func TestVariableRejectsMatcherFunctions(t *testing.T) {
	for _, value := range []string{
		"{{regexp.match(\"foo\")}}",
		"prefix{{regexp.not_match(\"foo\")}}suffix",
		"{{email.local(regexp.match(\"foo\"))}}",
	} {
		t.Run(value, func(t *testing.T) {
			_, err := Variable(value)
			if assert.True(t, trace.IsBadParameter(err), "error: %v", err) {
				expression := reVariable.FindStringSubmatch(value)[2]
				assert.EqualError(t, err, "matcher functions (like regexp.match) are not allowed here: "+strconv.Quote(expression))
			}
		})
	}
}

